```python
import os
from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse, JSONResponse
from fastapi.staticfiles import StaticFiles
from supermemory import Supermemory
import httpx

app = FastAPI()

if not os.path.exists("static"):
    os.makedirs("static")

MODAL_URL = os.environ.get("MODAL_BACKEND_URL")
SUPERMEMORY_KEY = os.environ.get("SUPERMEMORY_API_KEY")

sm_client = Supermemory(api_key=SUPERMEMORY_KEY)

@app.get("/", response_class=HTMLResponse)
async def read_index():
    with open("static/index.html", "r") as f:
        return f.read()

@app.post("/chat")
async def chat(data: dict):
    user_query = data.get("message")

    memories = sm_client.search.execute(q=user_query)
    context = "\n".join([m.content for m in memories.results]) if memories.results else ""

    system_prompt = f"Context from memory:\n{context}\n\nAnswer the user query based on context and your knowledge."

    payload = {
        "model": "zai-org/GLM-4.6-AWQ-4bit",
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_query}
        ],
        "temperature": 1.0,
        "top_k": 1,
        "max_tokens": 4096
    }

    async with httpx.AsyncClient(timeout=120.0) as client:
        response = await client.post(
            f"{MODAL_URL}/v1/chat/completions",
            json=payload,
            headers={"Authorization": f"Bearer {os.environ.get('MODAL_TOKEN_SECRET')}"}
        )
        return response.json()

app.mount("/static", StaticFiles(directory="static"), name="static")

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8080)
```

