### main.py
```python
import os
from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse, JSONResponse, StreamingResponse
from fastapi.staticfiles import StaticFiles
from supermemory import Supermemory
import httpx
import json

app = FastAPI()

if not os.path.exists("static"):
    os.makedirs("static")

MODAL_URL = os.environ.get("MODAL_BACKEND_URL")
SUPERMEMORY_KEY = os.environ.get("SUPERMEMORY_API_KEY")

sm_client = Supermemory(api_key=SUPERMEMORY_KEY)

@app.get("/", response_class=HTMLResponse)
async def read_index():
    with open("static/index.html", "r") as f:
        return f.read()

@app.post("/chat")
async def chat(request: Request):
    data = await request.json()
    user_query = data.get("message")
    conversation_history = data.get("history", [])

    try:
        search_results = sm_client.search.execute(
            q=user_query,
            limit=10,
            threshold=0.5
        )
        context = "\n".join([m.content for m in search_results.results]) if search_results.results else ""
    except:
        context = ""

    messages = []

    if context:
        messages.append({
            "role": "system",
            "content": f"You have access to the following context from long-term memory:\n\n{context}\n\nUse this information when relevant to answer the user's questions."
        })

    messages.extend(conversation_history)
    messages.append({"role": "user", "content": user_query})

    payload = {
        "model": MODEL_DIR,
        "messages": messages,
        "temperature": 1.0,
        "top_k": 1,
        "max_tokens": 8192,
        "stream": False
    }

    async with httpx.AsyncClient(timeout=180.0) as client:
        response = await client.post(
            f"{MODAL_URL}/v1/chat/completions",
            json=payload
        )
        result = response.json()

        assistant_message = result["choices"][0]["message"]["content"]

        try:
            sm_client.add.execute(
                content=f"User: {user_query}\nAssistant: {assistant_message}",
                metadata={"type": "conversation", "timestamp": data.get("timestamp", "")}
            )
        except:
            pass

        return result

app.mount("/static", StaticFiles(directory="static"), name="static")

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8080)
