    userInput.style.height = 'auto';

    const loadingDiv = appendMessage('...', 'bot');
    loadingDiv.innerHTML = '<span class="loading"></span><span class="loading" style="animation-delay: 0.2s;"></span><span class="loading" style="animation-delay: 0.4s;"></span>';

    try {
        const res = await fetch('/chat', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ 
                message: text,
                history: conversationHistory.slice(-10),
                timestamp: new Date().toISOString()
            })
        });

        if (!res.ok) throw new Error('Network response error');

        const data = await res.json();
        const botResponse = data.choices[0].message.content;

        loadingDiv.remove();
        appendMessage(botResponse, 'bot');
        conversationHistory.push({ role: 'assistant', content: botResponse });

    } catch (err) {
        loadingDiv.remove();
        appendMessage('Hiba történt a kapcsolódás során. Kérlek próbáld újra.', 'bot');
    }
}

function appendMessage(content, role) {
    const div = document.createElement('div');
    div.className = `message ${role}-msg`;
    div.textContent = content;
    chatWindow.appendChild(div);
    chatWindow.scrollTop = chatWindow.scrollHeight;
    return div;
}

sendBtn.addEventListener('click', sendMessage);

userInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        sendMessage();
    }
});

if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => {
        navigator.serviceWorker.register('/static/sw.js');
    });
}
