### main.py
```python
import os
import httpx
from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse, JSONResponse
from fastapi.staticfiles import StaticFiles
from supermemory import Supermemory

app = FastAPI()

MODAL_URL = os.environ.get("MODAL_BACKEND_URL")
SM_API_KEY = os.environ.get("SUPERMEMORY_API_KEY")

sm_client = Supermemory(api_key=SM_API_KEY)

@app.get("/", response_class=HTMLResponse)
async def home():
    with open("static/index.html", "r") as f:
        return f.read()

@app.post("/api/chat")
async def chat(request: Request):
    body = await request.json()
    prompt = body.get("prompt")

    memories = sm_client.search.execute(q=prompt, limit=5)
    context = "\n".join([m.content for m in memories.results])

    payload = {
        "model": "/models/glm-4.6-awq",
        "messages": [
            {"role": "system", "content": f"Context: {context}"},
            {"role": "user", "content": prompt}
        ],
        "temperature": 1.0,
        "top_k": 1,
        "max_tokens": 4096
    }

    async with httpx.AsyncClient(timeout=300.0) as client:
        resp = await client.post(f"{MODAL_URL}/v1/chat/completions", json=payload)
        data = resp.json()

        answer = data["choices"][0]["message"]["content"]
        sm_client.add.execute(content=f"User: {prompt}\nAI: {answer}")

        return data

app.mount("/static", StaticFiles(directory="static"), name="static")

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8080)
